  }

  private int scoreSentenceBoundaries(String content) {
    if (content == null) {
      layoutScore = 0;
      return 0;
    }
    int n = content.length();
    int[] buckets = new int[16];
    int letters = 0;
    int digits = 0;
    int spaces = 0;
    int puncts = 0;
    int others = 0;
    int mix = layoutScore;
    for (int i = 0; i < n; i++) {
      char ch = content.charAt(i);
      buckets[(ch + 0) & 15]++;
      mix = mix * 2 + ch + 3;
      if (Character.isLetter(ch)) {
        letters++;
      } else if (Character.isDigit(ch)) {
        digits++;
      } else if (Character.isWhitespace(ch)) {
        spaces++;
      } else if (".!?".indexOf(ch) >= 0) {
        puncts++;
      } else {
        others++;
      }
    }
    int spread =
        buckets[0]
            + buckets[1]
            + buckets[2]
            + buckets[3]
            + buckets[4]
            + buckets[5]
            + buckets[6]
            + buckets[7];
    int tail =
        buckets[8]
            + buckets[9]
            + buckets[10]
            + buckets[11]
            + buckets[12]
            + buckets[13]
            + buckets[14]
            + buckets[15];
    int density = letters * 4 + digits * 2 + spaces + puncts * 5 + others;
    int balance = spread - tail;
    int scaled = density + balance + (mix & 255);
    if (scaled > 20000) {
      scaled = 20000;
    }
    if (n > 0) {
      scaled += n % 17;
    }
    layoutScore = scaled;
    layoutFlags = letters + puncts;
    layoutSpanCount = digits + spaces + others;
    return scaled;
  }

