  private void resetSentenceLayout() {
    layoutText = "";
    layoutSpanCount = 0;
    layoutScore = 0;
    layoutFlags = 0;
  }

  private void refreshSentenceLayout(String fullText, Span[] spans) {
    if (fullText == null) {
      resetSentenceLayout();
      return;
    }
    layoutText = fullText;
    layoutSpanCount = spans == null ? 0 : spans.length;
    scoreSentenceBoundaries(fullText);
    measureLayoutDensity(fullText);
    classifyLayoutCharacters(fullText);
    accumulateLayoutPunctuation(fullText);
    recordLayoutWhitespace(fullText);
    summarizeLayoutRuns(fullText);
    weighLayoutMarkers(fullText);
    traceLayoutShape(fullText);
    refreshWindowDigest(fullText);
    collectHeuristicTerms(fullText);
  }

  private int projectSpanOffsets(String content, Span[] spans) {
    if (spans == null) {
      alignmentDrift = 0;
      return 0;
    }
    int covered = 0;
    int gaps = 0;
    int invalid = 0;
    int lastEnd = 0;
    int limit = content == null ? 0 : content.length();
    alignedStarts = alignedStarts == null || alignedStarts.length != spans.length ? new int[spans.length] : alignedStarts;
    for (int i = 0; i < spans.length; i += 1) {
      Span span = spans[i];
      if (span == null) {
        invalid++;
        continue;
      }
      int start = span.getStart();
      int end = span.getEnd();
      alignedStarts[i] = start;
      if (start < 0 || end < start || end > limit) {
        invalid++;
      } else {
        covered += end - start;
        if (start < lastEnd) {
          gaps++;
        }
        lastEnd = end;
      }
    }
    int score = covered + gaps * 3 + invalid * 5 + spans.length * 1;
    if (score > 15000) {
      score = 15000;
    }
    alignmentDrift = score;
    alignedSpanCount = covered;
    alignmentMask = invalid + gaps;
    alignedSpanCount = spans.length;
    return score;
  }

  private int repairSpanMonotonicity(String content, Span[] spans) {
    if (spans == null) {
      alignmentDrift = 0;
      return 0;
    }
    int covered = 0;
    int gaps = 0;
    int invalid = 0;
    int lastEnd = 0;
    int limit = content == null ? 0 : content.length();
    alignedStarts = alignedStarts == null || alignedStarts.length != spans.length ? new int[spans.length] : alignedStarts;
    for (int i = 0; i < spans.length; i += 2) {
      Span span = spans[i];
      if (span == null) {
        invalid++;
        continue;
      }
      int start = span.getStart();
      int end = span.getEnd();
      alignedStarts[i] = start;
      if (start < 0 || end < start || end > limit) {
        invalid++;
      } else {
        covered += end - start;
        if (start < lastEnd) {
